  "Dermatology & Cosmetology": [
    { patientId: "P-1097", author: "Dr. Tanya Kapoor", data: { diagnosis: "Psoriasis - Chronic Plaque", notes: "35-year-old with 5-year history of well-demarcated erythematous plaques with silvery scale on elbows, knees, and scalp. BSA 12%. PASI score 14. Started on Methotrexate 15mg weekly + Folic acid. Topical betamethasone for localized lesions. Phototherapy if no response in 3 months.", department: "Dermatology", vitals: { bp: "120/76", hr: 68 } } },
    { patientId: "P-1098", author: "Dr. Rohan Chawla", data: { diagnosis: "Acne Vulgaris - Moderate", notes: "19-year-old with comedonal and inflammatory acne on face for 2 years. Previous treatment with topical retinoids insufficient. Started on Isotretinoin 0.5mg/kg/day, titrating to 1mg/kg. Baseline labs: LFTs, lipids, CBC. Pregnancy prevention counseling. Monthly follow-up.", department: "Dermatology", vitals: { bp: "118/72", hr: 68 } } },
    { patientId: "P-1099", author: "Dr. Tanya Kapoor", data: { diagnosis: "Melanoma - Superficial Spreading (Stage IB)", notes: "42-year-old with changing mole on back. Excision biopsy: melanoma, Breslow thickness 1.2mm, no ulceration. Wide local excision with 2cm margins performed. Sentinel lymph node biopsy: negative. Follow-up: skin exams every 3 months, consider adjuvant therapy if high-risk features.", department: "Dermatology", vitals: { bp: "122/74", hr: 72 } } },
    { patientId: "P-1100", author: "Dr. Rohan Chawla", data: { diagnosis: "Rosacea - Erythematotelangiectatic", notes: "48-year-old female with persistent facial erythema and telangiectasias on cheeks and nose. Flushed easily with sun exposure and spicy food. Started on topical Ivermectin 1% cream. Sunscreen SPF 50 daily. Avoid triggers: alcohol, extreme temperatures. Laser therapy for telangiectasias planned.", department: "Dermatology", vitals: { bp: "118/72", hr: 66 } } },
    { patientId: "P-1101", author: "Dr. Tanya Kapoor", data: { diagnosis: "Contact Dermatitis - Allergic", notes: "30-year-old with itchy, vesicular rash on hands following new jewelry. Patch testing positive for Nickel. Allergic contact dermatitis confirmed. Avoidance of nickel-containing items. Potent topical steroid (Clobetasol) for acute phase. Emollients for barrier repair. Follow-up in 4 weeks.", department: "Dermatology", vitals: { bp: "115/70", hr: 68 } } },
    { patientId: "P-1102", author: "Dr. Rohan Chawla", data: { diagnosis: "Androgenetic Alopecia - Male Pattern (Norwood IV)", notes: "32-year-old with progressive frontoparietal hair loss for 5 years. Dermoscopy: hair diameter diversity, peripilar signs. Started on Finasteride 1mg daily + Minoxidil 5% topical. Platelet-rich plasma therapy discussed. Realistic expectations counseling provided.", department: "Dermatology", vitals: { bp: "120/76", hr: 70 } } },
    { patientId: "P-1103", author: "Dr. Tanya Kapoor", data: { diagnosis: "Vitiligo - Segmental", notes: "22-year-old with depigmented patch on right hand and wrist for 6 months. Wood's lamp confirms vitiligo. Segmental distribution. Started on topical Tacrolimus 0.1% for facial areas, potent topical steroid for body. Narrow-band UVB phototherapy initiated. Early treatment critical.", department: "Dermatology", vitals: { bp: "118/72", hr: 68 } } },
    { patientId: "P-1104", author: "Dr. Rohan Chawla", data: { diagnosis: "Photoaging & Solar Lentigines", notes: "55-year-old with multiple solar lentigines on face and dorsum of hands. Skin type III. History of chronic sun exposure. Q-switched Nd:YAG laser performed for lentigines. Tretinoin 0.025% cream for general photoaging. Strict sun protection reinforced.", department: "Dermatology", vitals: { bp: "122/74", hr: 72 } } },
    { patientId: "P-1105", author: "Dr. Tanya Kapoor", data: { diagnosis: "Seborrheic Dermatitis", notes: "40-year-old with recurrent erythematous, scaly patches on nasolabial folds, eyebrows, and scalp. Flares with stress and cold weather. Ketoconazole 2% cream for face, zinc pyrithione shampoo for scalp. Low-potency topical steroid for flares. Maintenance with moisturizers.", department: "Dermatology", vitals: { bp: "120/76", hr: 68 } } },
    { patientId: "P-1106", author: "Dr. Rohan Chawla", data: { diagnosis: "Chemical Peel - Melasma", notes: "35-year-old with bilateral malar hyperpigmentation (melasma). Fitzpatrick skin type IV. Previous treatment with hydroquinone partial response. Glycolic acid peel 35% performed. Sunscreen SPF 50 mandatory. Tri-Luma cream for maintenance. Series of 6 peels planned.", department: "Dermatology", vitals: { bp: "115/70", hr: 66 } } },
    { patientId: "P-1107", author: "Dr. Tanya Kapoor", data: { diagnosis: "Urticaria - Chronic Spontaneous", notes: "28-year-old with recurrent wheals and angioedema for >6 weeks. No identifiable trigger. Total IgE elevated. C4 low. Started on second-generation antihistamine (Cetirizine 10mg) doubled dose. Omalizumab considered if not controlled. Dermatographism positive.", department: "Dermatology", vitals: { bp: "118/72", hr: 72 } } },
    { patientId: "P-1108", author: "Dr. Rohan Chawla", data: { diagnosis: "Botulinum Toxin - Cosmetic", notes: "45-year-old female for cosmetic rejuvenation. Forehead lines, glabellar lines, and crow's feet. OnabotulinumtoxinA: 20 units glabella, 12 units forehead, 24 units crow's feet. Procedure well-tolerated. Results in 3-7 days, lasting 3-4 months. Avoid lying flat for 4 hours.", department: "Dermatology", vitals: { bp: "118/72", hr: 68 } } }
  ],
