console.log("=== HealthLedger Sample Data Generator ===\n");
console.log("Creating sample records for all departments...\n");

let totalRecords = 0;
for (const [department, records] of Object.entries(sampleRecords)) {
  console.log(`\n📁 ${department} (${records.length} records):`);
  for (const record of records) {
    try {
      ledger.addTransaction({
        patientId: record.patientId,
        author: record.author,
        data: record.data
      });
      console.log(`  ✓ ${record.patientId} - ${record.data.diagnosis} (by ${record.author})`);
      totalRecords++;
    } catch (error) {
      console.log(`  ✗ ${record.patientId} - Error: ${error.message}`);
    }
  }
}

console.log(`\n\n=== Summary ===`);
console.log(`Total records created: ${totalRecords}`);
console.log(`Departments covered: ${Object.keys(sampleRecords).length}`);
console.log(`\nTo add these records to your blockchain, run the API server and submit records via POST /api/records`);
console.log(`\nAlternatively, you can mine these transactions into the blockchain.`);
